const data = $('Fusionner Donn\u00e9es').first().json;
const gemma = $('Gemma 4 (RAG)').first().json;

const stats = data.stats || {};
const kpis = data.kpis || {};
const trend = data.trend || {};
const queue = data.queue || {};
const today = data.today;

// R\u00e9ponse IA
let aiAnswer = '';
let llmUsed = 'N/A';
let responseTime = '';
if (gemma && gemma.answer) {
  aiAnswer = gemma.answer;
  llmUsed = gemma.llm_used || 'gemma4';
  responseTime = gemma.response_time_ms ? (gemma.response_time_ms / 1000).toFixed(1) + 's' : '';
} else {
  aiAnswer = 'Le r\u00e9sum\u00e9 IA n\'a pas pu \u00eatre g\u00e9n\u00e9r\u00e9. Consultez les donn\u00e9es ci-dessous.';
}

// Markdown \u2192 HTML basique
const aiHtml = aiAnswer
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.*?)\*/g, '<em>$1</em>')
  .replace(/^### (.*$)/gm, '<h4 style="margin:12px 0 4px;color:#4A148C;">$1</h4>')
  .replace(/^## (.*$)/gm, '<h3 style="margin:15px 0 5px;color:#4A148C;">$1</h3>')
  .replace(/^- (.*$)/gm, '\u2022 $1<br>')
  .replace(/^\d+\. (.*$)/gm, '$1<br>')
  .replace(/\n/g, '<br>');

// Tendances
const deltaTickets = trend.deltaTickets != null ? (trend.deltaTickets > 0 ? '+' : '') + Number(trend.deltaTickets).toFixed(0) + '%' : 'N/A';
const deltaResolution = trend.deltaResolution != null ? (trend.deltaResolution > 0 ? '+' : '') + Number(trend.deltaResolution).toFixed(0) + '%' : 'N/A';
const trendColorT = (trend.deltaTickets || 0) > 0 ? '#C62828' : '#2E7D32';
const trendColorR = (trend.deltaResolution || 0) > 0 ? '#2E7D32' : '#C62828';

const total = stats.total || 0;
const tauxRes = kpis.tauxResolution != null ? Number(kpis.tauxResolution).toFixed(0) : 'N/A';
const tempsMoyen = kpis.tempsMoyenMinutes != null ? Number(kpis.tempsMoyenMinutes).toFixed(0) : 'N/A';
const queueCount = queue.totalEnAttente || 0;

const html = '<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f0f0f0;">' +
'<div style="font-family:Segoe UI,Arial,sans-serif;max-width:700px;margin:20px auto;">' +

  // HEADER
  '<div style="background:linear-gradient(135deg,#1A237E,#4A148C,#7B1FA2);color:white;padding:30px;border-radius:16px 16px 0 0;text-align:center;">' +
    '<div style="font-size:40px;margin-bottom:8px;">\ud83d\udcca</div>' +
    '<h1 style="margin:0;font-size:22px;letter-spacing:0.5px;">Tableau de Bord IA</h1>' +
    '<p style="margin:6px 0 0;opacity:0.85;font-size:14px;">AutoAssist \u2014 ' + today + '</p>' +
    (llmUsed !== 'N/A' ? '<p style="margin:4px 0 0;opacity:0.6;font-size:11px;">Analys\u00e9 par ' + llmUsed + ' en ' + responseTime + '</p>' : '') +
  '</div>' +

  // KPI CARDS
  '<div style="background:white;padding:20px;border-left:1px solid #e0e0e0;border-right:1px solid #e0e0e0;">' +
    '<table style="width:100%;border-spacing:8px;border-collapse:separate;"><tr>' +
      '<td style="background:linear-gradient(135deg,#E3F2FD,#BBDEFB);border-radius:12px;padding:18px;text-align:center;width:25%;">' +
        '<div style="font-size:32px;font-weight:800;color:#1565C0;">' + total + '</div>' +
        '<div style="font-size:11px;color:#555;margin-top:4px;">Total tickets</div>' +
      '</td>' +
      '<td style="background:linear-gradient(135deg,#E8F5E9,#C8E6C9);border-radius:12px;padding:18px;text-align:center;width:25%;">' +
        '<div style="font-size:32px;font-weight:800;color:#2E7D32;">' + tauxRes + '<span style="font-size:16px;">%</span></div>' +
        '<div style="font-size:11px;color:#555;margin-top:4px;">R\u00e9solution</div>' +
      '</td>' +
      '<td style="background:linear-gradient(135deg,#FFF3E0,#FFE0B2);border-radius:12px;padding:18px;text-align:center;width:25%;">' +
        '<div style="font-size:32px;font-weight:800;color:#E65100;">' + tempsMoyen + '<span style="font-size:14px;">min</span></div>' +
        '<div style="font-size:11px;color:#555;margin-top:4px;">Temps moyen</div>' +
      '</td>' +
      '<td style="background:linear-gradient(135deg,#FCE4EC,#F8BBD0);border-radius:12px;padding:18px;text-align:center;width:25%;">' +
        '<div style="font-size:32px;font-weight:800;color:#C62828;">' + queueCount + '</div>' +
        '<div style="font-size:11px;color:#555;margin-top:4px;">En file</div>' +
      '</td>' +
    '</tr></table>' +
  '</div>' +

  // DETAILS
  '<div style="background:#FAFAFA;padding:20px;border-left:1px solid #e0e0e0;border-right:1px solid #e0e0e0;">' +
    '<table style="width:100%;border-collapse:collapse;">' +
      '<tr style="background:#EDE7F6;"><th colspan="4" style="padding:10px;text-align:left;font-size:13px;color:#4A148C;">\ud83d\udce6 R\u00e9partition par statut</th></tr>' +
      '<tr>' +
        '<td style="padding:10px;text-align:center;"><div style="font-size:20px;font-weight:700;color:#1976D2;">' + (stats.nouveau || 0) + '</div><div style="font-size:10px;color:#888;">Nouveaux</div></td>' +
        '<td style="padding:10px;text-align:center;"><div style="font-size:20px;font-weight:700;color:#F57C00;">' + (stats.enCours || 0) + '</div><div style="font-size:10px;color:#888;">En cours</div></td>' +
        '<td style="padding:10px;text-align:center;"><div style="font-size:20px;font-weight:700;color:#2E7D32;">' + (stats.resolu || 0) + '</div><div style="font-size:10px;color:#888;">R\u00e9solus</div></td>' +
        '<td style="padding:10px;text-align:center;"><div style="font-size:20px;font-weight:700;color:#757575;">' + (stats.ferme || 0) + '</div><div style="font-size:10px;color:#888;">Ferm\u00e9s</div></td>' +
      '</tr>' +
    '</table>' +
  '</div>' +

  // CANAUX + DECISIONS IA
  '<div style="background:white;padding:20px;border-left:1px solid #e0e0e0;border-right:1px solid #e0e0e0;">' +
    '<table style="width:100%;border-collapse:collapse;">' +
      '<tr>' +
        '<td style="width:50%;vertical-align:top;padding-right:10px;">' +
          '<div style="font-size:12px;font-weight:700;color:#4A148C;margin-bottom:8px;">\ud83d\udcde Canaux</div>' +
          '<div style="background:#F5F5F5;border-radius:8px;padding:12px;">' +
            '<div style="margin-bottom:6px;"><span style="color:#1565C0;">\u260e</span> Appels: <strong>' + (kpis.ticketsCall || 0) + '</strong></div>' +
            '<div style="margin-bottom:6px;"><span style="color:#EF6C00;">\u2709</span> Emails: <strong>' + (kpis.ticketsEmail || 0) + '</strong></div>' +
            '<div><span style="color:#2E7D32;">\ud83c\udf10</span> Web: <strong>' + (kpis.ticketsWeb || 0) + '</strong></div>' +
          '</div>' +
        '</td>' +
        '<td style="width:50%;vertical-align:top;padding-left:10px;">' +
          '<div style="font-size:12px;font-weight:700;color:#4A148C;margin-bottom:8px;">\ud83e\udd16 D\u00e9cisions IA</div>' +
          '<div style="background:#F5F5F5;border-radius:8px;padding:12px;">' +
            '<div style="margin-bottom:6px;"><span style="color:#2E7D32;">\u2705</span> Favorables: <strong>' + (kpis.decisionsAiFavorable || 0) + '</strong></div>' +
            '<div style="margin-bottom:6px;"><span style="color:#C62828;">\u274c</span> D\u00e9favorables: <strong>' + (kpis.decisionsAiDefavorable || 0) + '</strong></div>' +
            '<div><span style="color:#F57C00;">\ud83d\udd0d</span> En \u00e9tude: <strong>' + (kpis.decisionsAiEtude || 0) + '</strong></div>' +
          '</div>' +
        '</td>' +
      '</tr>' +
    '</table>' +
  '</div>' +

  // TENDANCES
  '<div style="background:#FAFAFA;padding:15px 20px;border-left:1px solid #e0e0e0;border-right:1px solid #e0e0e0;">' +
    '<div style="font-size:12px;font-weight:700;color:#4A148C;margin-bottom:8px;">\ud83d\udcc8 Tendances vs semaine pr\u00e9c\u00e9dente</div>' +
    '<table style="width:100%;"><tr>' +
      '<td style="text-align:center;"><span style="font-size:18px;font-weight:700;color:' + trendColorT + ';">' + deltaTickets + '</span><br><span style="font-size:10px;color:#888;">Volume tickets</span></td>' +
      '<td style="text-align:center;"><span style="font-size:18px;font-weight:700;color:' + trendColorR + ';">' + deltaResolution + '</span><br><span style="font-size:10px;color:#888;">Taux r\u00e9solution</span></td>' +
    '</tr></table>' +
  '</div>' +

  // ANALYSE IA (GEMMA 4)
  '<div style="background:white;padding:20px;border-left:1px solid #e0e0e0;border-right:1px solid #e0e0e0;">' +
    '<div style="background:linear-gradient(135deg,#EDE7F6,#E8EAF6);border-radius:12px;padding:20px;border-left:4px solid #7B1FA2;">' +
      '<div style="font-size:14px;font-weight:700;color:#4A148C;margin-bottom:10px;">\ud83e\udde0 Analyse IA \u2014 Gemma 4</div>' +
      '<div style="line-height:1.7;color:#333;font-size:13px;">' + aiHtml + '</div>' +
    '</div>' +
  '</div>' +

  // FOOTER
  '<div style="background:linear-gradient(135deg,#37474F,#263238);padding:20px;border-radius:0 0 16px 16px;text-align:center;">' +
    '<a href="http://localhost:3000/dashboard" style="color:#BB86FC;font-weight:700;text-decoration:none;font-size:14px;">\ud83d\udcca Ouvrir le Dashboard</a>' +
    '<p style="color:#78909C;font-size:10px;margin:10px 0 0;">\u00a9 2026 AutoAssist \u2014 Orchestration n8n \u00b7 IA Gemma 4 \u00b7 4 microservices</p>' +
  '</div>' +

'</div></body></html>';

return [{ json: { html: html, subject: '\ud83d\udcca Tableau de Bord IA \u2014 ' + today } }];
